/* 每日记录：每条记录拥有自己的卡片内照片区。 */
.bl-record-entry-photos {
  padding-bottom: 16px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--c-soft);
}
.bl-record-source-tab { font-weight: 500; }
/* 包装识别：与照片编辑操作同一行，使用相同按钮尺寸。 */
.bl-photo-recognition > div {
  margin-top: 0;
}
.bl-photo-recognition [role="group"] {
  justify-content: flex-start;
  gap: 12px;
  margin-top: 0;
}
.bl-photo-recognition [role="group"] button {
  min-width: 84px;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid var(--c-primary);
  border-radius: 999px;
  background: var(--c-primary);
  box-shadow: none !important;
  color: var(--c-primary-ink);
  font-size: 12px;
  font-weight: 400;
  line-height: 16px;
}
.bl-photo-recognition [role="group"] button[aria-pressed="false"] {
  color: var(--c-ink-faint);
}
/* 豆袋照片：正方形满幅裁切，安全别针穿过右上边缘的纸面。 */
.bl-bean-photo {
  width: 50%;
  margin-inline: auto;
  aspect-ratio: 1 / 1;
  overflow: visible;
}
.bl-bean-photo > img {
  width: 100%;
  height: 100%;
  border-radius: 15px;
  object-fit: cover;
}
/* 有照片时直接点击照片更换，不再显示右下角浮层。 */
.bl-bean-photo:has(> img) > span:last-child {
  display: none;
}
.bl-archive-pin {
  position: absolute;
  z-index: 2;
  top: -10px;
  right: -5px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border: 0;
  background: transparent;
  font-family: "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif;
  font-size: 40px;
  line-height: 1;
  filter: drop-shadow(1px 2px 1px rgba(45, 40, 32, 0.18));
  transform: rotate(-90deg);
  -webkit-mask-image: linear-gradient(45deg, #000 0%, #000 42%, transparent 46%, transparent 54%, #000 58%, #000 100%), linear-gradient(-45deg, #000 0%, #000 50%, transparent 50%, transparent 100%);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(45deg, #000 0%, #000 42%, transparent 46%, transparent 54%, #000 58%, #000 100%), linear-gradient(-45deg, #000 0%, #000 50%, transparent 50%, transparent 100%);
  mask-composite: intersect;
  overflow: visible;
  pointer-events: none;
}
.bl-pin-puncture {
  position: absolute;
  z-index: 3;
  width: 4px;
  height: 2px;
  border-radius: 50%;
  background: rgba(55, 47, 37, 0.58);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.65), 0 0 2px rgba(55, 47, 37, 0.2);
  transform: rotate(45deg);
  pointer-events: none;
}
.bl-pin-puncture-a {
  top: 6px;
  right: 24px;
}
.bl-pin-puncture-b {
  top: 20px;
  right: 10px;
}
/* 豆子身份：资料行使用舒适行高，风味输入框保持紧凑。 */
.bl-identity-field {
  height: 50px;
  padding-top: 0;
  padding-bottom: 0;
  align-items: center;
}
.bl-identity-textarea {
  height: 32px;
  min-height: 32px;
  padding-top: 4px;
  padding-bottom: 4px;
}
/* 豆袋详情：整张页面作为档案封面，照片别在右上角。 */
.bl-bean-detail {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 172px;
  column-gap: 14px;
  padding: 0 16px 64px;
  background:
    linear-gradient(90deg, transparent 0 31px, rgb(var(--c-accent) / 0.055) 31px 32px, transparent 32px),
    var(--c-app);
}
.bl-bean-detail > .sticky {
  grid-column: 1 / -1;
  margin: 0 -16px;
  border-bottom: 1px solid rgb(var(--c-line) / 0.65);
}
.bl-bean-detail > div:nth-child(2) {
  position: relative;
  grid-column: 1;
  grid-row: 2;
  align-self: start;
  min-height: 184px;
  margin: 22px 0 0;
  padding: 18px 4px 16px 14px;
  border-top: 1px solid var(--c-line);
  border-bottom: 1px solid var(--c-line);
  background: linear-gradient(180deg, rgb(var(--c-surface) / 0.5), transparent 75%);
}
.bl-bean-detail > div:nth-child(2)::before {
  content: "BEAN ARCHIVE  /  豆子档案";
  display: block;
  margin-bottom: 18px;
  color: var(--c-accent);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1.6px;
}
.bl-bean-detail > div:nth-child(2)::after {
  content: "COFFEE LAB\A FIELD RECORD";
  position: absolute;
  left: 14px;
  bottom: 15px;
  padding: 5px 7px;
  border: 1px solid rgb(var(--c-accent) / 0.38);
  border-radius: 3px;
  color: rgb(var(--c-accent) / 0.68);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 9px;
  line-height: 1.45;
  letter-spacing: 1px;
  white-space: pre;
  transform: rotate(-4deg);
}
#root .bl-bean-detail > div:nth-child(2) > textarea {
  display: block;
  width: 100%;
  min-height: 31px;
  height: auto;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  outline: none;
  background: transparent;
  box-shadow: none;
  appearance: none;
  -webkit-appearance: none;
  font-size: 23px;
  line-height: 1.35;
  overflow-wrap: anywhere;
  word-break: break-word;
  resize: none;
}
/* 标题下方的购买状态：圆形滑钮左右移动，文字只显示当前状态。 */
.bl-purchase-switch {
  position: relative;
  display: block;
  width: 100px;
  height: 38px;
  margin: 14px 0 50px;
  padding: 3px;
  border: 1px solid rgb(var(--c-line) / 0.9);
  border-radius: 999px;
  background: rgb(var(--c-soft) / 0.85);
  box-shadow: inset 0 1px 3px rgb(var(--c-shadow) / 0.1);
  cursor: pointer;
  transition: background 180ms ease;
  -webkit-tap-highlight-color: transparent;
}
.bl-purchase-switch[aria-checked="true"] {
  background: var(--c-primary);
}
.bl-purchase-switch-thumb {
  position: absolute;
  z-index: 1;
  top: 3px;
  left: 3px;
  width: 30px;
  height: 30px;
  border: 1px solid rgb(var(--c-line) / 0.7);
  border-radius: 50%;
  background: linear-gradient(145deg, #fff 15%, var(--c-surface) 70%, var(--c-soft));
  box-shadow: 0 2px 5px rgb(var(--c-shadow) / 0.24), inset 0 1px 1px #fff;
  transition: transform 180ms ease;
}
.bl-purchase-switch[aria-checked="true"] .bl-purchase-switch-thumb {
  transform: translateX(64px);
}
.bl-purchase-switch-label {
  position: absolute;
  top: 3px;
  right: 5px;
  left: 37px;
  color: var(--c-ink);
  font-size: 12px;
  font-weight: 500;
  line-height: 30px;
  text-align: center;
  pointer-events: none;
}
.bl-purchase-switch[aria-checked="true"] .bl-purchase-switch-label {
  right: 37px;
  left: 5px;
  color: var(--c-primary-ink);
}
.bl-purchase-switch:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 3px;
}
.bl-bean-detail > div:nth-child(3) {
  display: contents;
}
.bl-bean-detail .bl-bean-photo {
  grid-column: 2;
  grid-row: 2;
  align-self: start;
  width: 164px;
  margin: 32px 2px 0 auto;
  border: 5px solid var(--c-surface);
  border-radius: 3px;
  box-shadow: 0 7px 16px rgb(var(--c-shadow) / 0.18);
  transform: rotate(1.5deg);
}
.bl-bean-detail .bl-bean-photo > img {
  border-radius: 1px;
}
.bl-bean-detail .bl-archive-pin {
  top: -17px;
  right: -13px;
}
.bl-bean-detail .bl-edit-photo {
  grid-column: 2;
  grid-row: 3;
  align-self: start;
  justify-self: center;
  justify-content: center;
  min-width: 104px;
  margin-top: 0;
}
.bl-bean-detail > div:nth-child(3) > div {
  z-index: 1;
  grid-column: 1;
  grid-row: 2;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-self: end;
  align-items: center;
  justify-self: end;
  justify-content: flex-start;
  gap: 6px;
  margin: 0 4px 66px 0;
}
.bl-bean-detail > div:nth-child(3) .bl-photo-recognition {
  margin: 0;
}
.bl-bean-detail > div:nth-child(3) > div > button {
  min-width: 84px;
  min-height: 40px;
  justify-content: center;
  font-size: 11px;
}
.bl-bean-detail > div:nth-child(3) > div > button:last-of-type {
  display: none;
}
.bl-bean-detail > div:nth-child(4) {
  grid-column: 1 / -1;
  grid-row: 4;
  margin: 22px -4px 0;
  padding: 0;
}
.bl-bean-detail .bl-record-folder {
  position: relative;
}
.bl-bean-detail .bl-record-index {
  padding-left: 7px;
}
.bl-bean-detail .bl-record-tab {
  letter-spacing: 0.04em;
}
.bl-bean-detail .bl-record-sheet {
  border: 1px solid var(--c-line);
  background:
    linear-gradient(90deg, transparent 0 28px, color-mix(in srgb, var(--c-accent) 4.5%, transparent) 28px 29px, transparent 29px),
    var(--c-surface);
  box-shadow: 0 8px 22px rgb(var(--c-shadow) / 0.08), 4px 4px 0 color-mix(in srgb, var(--c-soft) 55%, transparent);
}
.bl-bean-detail .bl-record-page-content {
  position: relative;
}
.bl-bean-detail > button {
  grid-column: 1 / -1;
  grid-row: 5;
  justify-self: center;
}
.bl-bean-detail > div:nth-child(5) {
  grid-column: 1 / -1;
  grid-row: 5;
}
@media (max-width: 380px) {
  .bl-bean-detail {
    grid-template-columns: minmax(0, 1fr) 142px;
    column-gap: 10px;
    padding-inline: 12px;
  }
  .bl-bean-detail > .sticky {
    margin-inline: -12px;
  }
  .bl-bean-detail .bl-bean-photo {
    width: 134px;
  }
  .bl-bean-detail > div:nth-child(2) > input {
    font-size: 20px;
  }
}


